from collections.abc import Mapping
import copy


def _validate(value, active):
    if isinstance(value, Mapping):
        marker = id(value)
        if marker in active:
            raise ValueError('cyclic value')
        active.add(marker)
        for key, child in value.items():
            if not isinstance(key, str):
                raise ValueError('keys must be strings')
            _validate(child, active)
        active.remove(marker)
    elif isinstance(value, (list, tuple)):
        marker = id(value)
        if marker in active:
            raise ValueError('cyclic value')
        active.add(marker)
        for child in value:
            _validate(child, active)
        active.remove(marker)
    elif value is not None and not isinstance(value, (bool, int, float, str)):
        raise ValueError('unsupported value')


def assemble_bundle(defaults, override=None):
    if not isinstance(defaults, Mapping) or (override is not None and not isinstance(override, Mapping)):
        raise ValueError('arguments must be mappings')
    override = {} if override is None else override
    _validate(defaults, set())
    _validate(override, set())

    def merge(left, right):
        result = dict(left)
        for key, value in right.items():
            if key in left and isinstance(left[key], Mapping) and isinstance(value, Mapping):
                result[key] = merge(left[key], value)
            else:
                result[key] = copy.deepcopy(value)
        return result

    return merge(defaults, override)
